def text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([text(k) + ' ' + text(v) for k, v in x.items()])
    return str(x).lower()

def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    return ''

def hook(ctx, nb):
    tt = text(val(ctx, 'task.task_type', ''))
    target = text(val(ctx, 'task.target_type', ''))
    dest = text(val(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    act = text(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(val(ctx, 'world.inventory', ''))
    if verb and target and act.startswith(verb + ' ') and target in act and 'nothing happens' not in obs:
        nb['transformed'] = True
    if verb and target and target in obs and ('you ' + verb) in obs and 'using' in obs:
        nb['transformed'] = True
    if verb and target and act.startswith('put ') and target in act and 'you put' in obs and verb not in act:
        nb['transformed'] = False
    pc = val(ctx, 'world.placed_count', None)
    if isinstance(pc, int):
        nb['placed_count'] = pc
    locs = val(ctx, 'world.placed_locations', None)
    if isinstance(locs, (list, tuple, set)):
        nb['placed_locations'] = [text(x) for x in locs]
    elif locs:
        nb['placed_locations'] = [text(locs)]
    carrying = bool(target and target in inv and 'nothing' not in inv and 'not carrying' not in inv)
    wrong = bool(inv and 'nothing' not in inv and 'not carrying' not in inv and target and target not in inv)
    adm = [text(a) for a in (ctx.get('admissible') or [])]
    take_here = bool(target and any(a.startswith('take ') and target in a for a in adm))
    put_here = bool(target and dest and any(a.startswith('put ') and target in a and dest in a for a in adm))
    trans_here = bool(verb and target and any(a.startswith(verb + ' ') and target in a for a in adm))
    if wrong:
        stage = 'wrong_inventory'
    elif carrying and verb and not nb.get('transformed'):
        stage = 'transform'
    elif carrying and put_here:
        stage = 'put_target'
    elif carrying:
        stage = 'go_destination'
    elif take_here or val(ctx, 'world.target_found', False):
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['required_verb'] = verb
    return None

