def hook(ctx, nb):
    stage = nb.get('stage')
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb') or needverb(nb.get('task_type') or text(val(ctx, 'task.task_type', '')))
    tt = nb.get('task_type') or text(val(ctx, 'task.task_type', ''))
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You are carrying a non-target item. Do not place it as the goal object; recover by setting it down only if needed, then find the target type.'
    elif stage == 'transform' and verb and target:
        msg = 'This target needs to be ' + verb + 'ed before placement. Carry it to the proper appliance or basin and use the ' + verb + ' action before putting it at the destination.'
    elif stage == 'put_target' and target and dest:
        msg = 'You are at the destination with the target. Use the put action for ' + target + ' in/on ' + dest + ' now.'
    elif stage == 'take_target' and target:
        msg = 'A target ' + target + ' is available here. Take it instead of continuing to search or inspect unrelated objects.'
    elif stage == 'find_target' and 'two' in tt and nb.get('placed_count', 0) > 0 and target:
        msg = 'One ' + target + ' is already placed. Do not take it back; find another ' + target + ' and use the same destination.'
    elif stage == 'find_target' and 'two' in tt and nb.get('placed_count', 0) == 1 and target:
        msg = 'One ' + target + ' is already placed. Leave it there, find another ' + target + ', and return to the same destination.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

